insert into public.roles (code, name, description) values ('guest','Guest','Try learning features without an authenticated student account.'),('student','Student','Learning, activity, challenge, progress, exam, and project.'),('teacher','Teacher','Content, class, student progress, assessment, and activity generator.'),('admin','Admin','System configuration and operational administration.') on conflict (code) do update set name=excluded.name, description=excluded.description;;
